  // Given wake time, find best sleep times (6 or 5 or 4 cycles back)
  const times=[];
  for(let c=6;c>=4;c--){
    const sleepMin=((base-(c*cycleMin+fallAsleep))+1440)%1440;
    const sh=Math.floor(sleepMin/60).toString().padStart(2,'0');
    const sm=(sleepMin%60).toString().padStart(2,'0');
    times.push({t:`${sh}:${sm}`,c,best:c===6});
  }
  slots=times.map(x=>`<div class="sleep-slot${x.best?' best':''}">${x.best?'⭐ ':''}${x.t} (${x.c} cycles)</div>`).join('');
  el.innerHTML=`<div class="rnum">Go to sleep at…</div><div class="rsub">To wake at ${t.value} feeling refreshed:</div><div class="sleep-slots">${slots}</div><div style="font-size:11px;color:var(--tx3);margin-top:8px;">⭐ = Ideal (6 cycles = ~9 hrs). Each cycle = 90 min.</div>`;
} else {
  // Given sleep time, find best wake times (4, 5, 6 cycles forward)
  const times=[];
  for(let c=4;c<=6;c++){
    const wakeMin=((base+c*cycleMin+fallAsleep)+1440)%1440;
    const wh=Math.floor(wakeMin/60).toString().padStart(2,'0');
    const wm=(wakeMin%60).toString().padStart(2,'0');
    times.push({t:`${wh}:${wm}`,c,best:c===6});
