const req = parseFloat(document.getElementById('attReq')&&document.getElementById('attReq').value)||75;
if (!total || attended > total) { setRes('attend','—','Enter valid values',''); return; }
const curPct = (attended/total*100).toFixed(1);
const status = curPct >= req ? '✅ SAFE' : '❌ SHORTAGE';
const color = curPct >= req ? 'var(--gr)' : 'var(--re)';
// How many more classes can be missed and still meet req
let canMiss = 0, needAttend = 0;
if (curPct >= req) {
  // Max classes can miss: attended + future - req*(total+future) >= 0 → solve
  // canMiss: (attended - req*(total+canMiss)) / (1-req) ≤ 0 ... binary approach
  for (let m = 0; m <= 200; m++) {
    if ((attended / (total + m)) * 100 < req) { canMiss = m - 1; break; }
    if (m === 200) canMiss = 200;
  }
} else {
  // How many consecutive classes to attend
  for (let a = 0; a <= 500; a++) {
    if (((attended + a) / (total + a)) * 100 >= req) { needAttend = a; break; }
    if (a === 500) needAttend = -1;
  }
}
const sub = curPct >= req
  ? `Current: ${attended}/${total}<br>Required: ${req}%<br>Can miss: ${canMiss} more classes<br>Status: Safe zone ✅`
  : `Current: ${attended}/${total}<br>Required: ${req}%<br>Must attend next: ${needAttend} classes<br>Status: Shortage ❌`;
