// plot
// Safe maths parser (no Function constructor / eval): numbers, x, + - * / % ^ **,
// parentheses, pi, e, and sin cos tan asin acos atan sqrt log ln abs exp.
// 'Math.' prefixes are accepted (Math.sin(x) -> sin(x)).
function makeFn(src){
  var s=String(src||'').replace(/\s+/g,'').replace(/Math\./g,'');
  var pos=0, curX=0;
  function parseExpr(){var v=parseTerm();while(pos<s.length){if(s.charAt(pos)==='+'){pos++;v=v+parseTerm();}else if(s.charAt(pos)==='-'){pos++;v=v-parseTerm();}else{break;}}return v;}
  function parseTerm(){var v=parseFactor();while(pos<s.length){if(s.charAt(pos)==='*'){pos++;v=v*parseFactor();}else if(s.charAt(pos)==='/'){pos++;v=v/parseFactor();}else if(s.charAt(pos)==='%'){pos++;v=v%parseFactor();}else{break;}}return v;}
  function parseFactor(){var v=parseUnary();if(s.substr(pos,2)==='**'){pos+=2;v=Math.pow(v,parseFactor());}else if(s.charAt(pos)==='^'){pos++;v=Math.pow(v,parseFactor());}return v;}
  function parseUnary(){if(s.charAt(pos)==='-'){pos++;return -parseUnary();}if(s.charAt(pos)==='+'){pos++;return parseUnary();}return parsePrimary();}
  function parsePrimary(){
    if(s.charAt(pos)==='('){pos++;var v=parseExpr();if(s.charAt(pos)!==')')throw new Error('missing )');pos++;return v;}
    var m=/^[0-9]*\.?[0-9]+/.exec(s.slice(pos));
    if(m){pos+=m[0].length;return parseFloat(m[0]);}
    var id=/^[a-zA-Z]+/.exec(s.slice(pos));
    if(id){
      var name=id[0].toLowerCase();pos+=id[0].length;
      if(name==='x')return curX;
      if(name==='pi')return Math.PI;
      if(name==='e')return Math.E;
      if(['sin','cos','tan','asin','acos','atan','sqrt','log','ln','abs','exp'].indexOf(name)!==-1){
        if(s.charAt(pos)!=='(')throw new Error('expected (');
        pos++;var arg=parseExpr();
        if(s.charAt(pos)!==')')throw new Error('missing )');
        pos++;
        if(name==='sin')return Math.sin(arg);if(name==='cos')return Math.cos(arg);
        if(name==='tan')return Math.tan(arg);if(name==='asin')return Math.asin(arg);
        if(name==='acos')return Math.acos(arg);if(name==='atan')return Math.atan(arg);
        if(name==='sqrt')return Math.sqrt(arg);
        if(name==='log'||name==='ln')return Math.log(arg);
        if(name==='abs')return Math.abs(arg);
        if(name==='exp')return Math.exp(arg);
      }
      throw new Error('unknown name '+name);
    }
    throw new Error('unexpected '+s.charAt(pos));
  }
  return function(x){curX=x;pos=0;var v=parseExpr();if(pos<s.length)throw new Error('trailing input');return v;};
}
