var sum=nums.reduce(function(a,b){return a+b;},0);
var mean=sum/n;
var median=n%2===0?(nums[n/2-1]+nums[n/2])/2:nums[Math.floor(n/2)];
var variance=nums.reduce(function(a,b){return a+Math.pow(b-mean,2);},0)/n;
var stddev=Math.sqrt(variance);
var range=nums[n-1]-nums[0];
// Mode
var freq={};nums.forEach(function(x){freq[x]=(freq[x]||0)+1;});
var maxF=Math.max.apply(null,Object.values(freq));
var modes=Object.keys(freq).filter(function(k){return freq[k]===maxF;});
var mode=maxF>1?modes.join(', '):'None';
var res=document.getElementById('res-stats');
if(res)res.innerHTML='<div class="salary-breakdown">'+
    '<div class="sb-item"><div class="sb-val">'+mean.toFixed(3)+'</div><div class="sb-lbl">Mean (Avg)</div></div>'+
    '<div class="sb-item"><div class="sb-val">'+median+'</div><div class="sb-lbl">Median</div></div>'+
    '<div class="sb-item"><div class="sb-val">'+mode+'</div><div class="sb-lbl">Mode</div></div>'+
    '<div class="sb-item"><div class="sb-val">'+range+'</div><div class="sb-lbl">Range</div></div>'+
    '<div class="sb-item"><div class="sb-val">'+variance.toFixed(3)+'</div><div class="sb-lbl">Variance</div></div>'+
    '<div class="sb-item"><div class="sb-val">'+stddev.toFixed(3)+'</div><div class="sb-lbl">Std Dev (σ)</div></div>'+
    '</div><div style="padding:8px 0 0;font-size:11px;color:var(--tx3);">Count: '+n+' | Sum: '+sum+' | Min: '+nums[0]+' | Max: '+nums[n-1]+'</div>';

