const shape=getId('arS'),a=parseFloat(getId('arA'))||0,b=parseFloat(getId('arB'))||0;
var _hc=parseFloat(getId('arC'));var h=isNaN(_hc)?0:_hc;
let area=0,perim=0,note='';
if(a<=0){showValError('area','First dimension must be greater than 0');return;}
if(shape!=='Square'&&shape!=='Circle'&&b<=0){showValError('area','Second dimension must be greater than 0');return;}
if(shape==='Trapezoid'&&h<=0){showValError('area','Height (c) is needed for a trapezoid');return;}
if(shape==='Square'){area=a*a;perim=4*a;note=`Side = ${a}`;}
else if(shape==='Rectangle'){area=a*b;perim=2*(a+b);note=`L=${a}, W=${b}`;}
else if(shape==='Triangle'){area=.5*a*b;perim=a+b+Math.sqrt(a*a+b*b);note=`Base=${a}, Height=${b}`;}
else if(shape==='Circle'){area=Math.PI*a*a;perim=2*Math.PI*a;note=`Radius=${a}`;}
else if(shape==='Trapezoid'){area=.5*(a+b)*h;note=`Parallel sides: a=${a}, b=${b}, height=${h}`;}
var perimTxt=(shape==='Trapezoid')?'Perimeter: needs the two non-parallel sides':('Perimeter/Circumference: '+fmt(perim));
setRes('area',fmt(area),`Area (${shape})`,perimTxt+`<br>${note}<br>Area = ${fmt(area)} sq units`);

