if(navigator.vibrate)navigator.vibrate(6);
switch(a){
  case'ac':buf='';cur='0';setD('0','');dSteps.textContent='';break;
  case'back':
    if(buf&&(cur==='0'||cur===''))buf=buf.slice(0,-1);
    else cur=cur.length>1?cur.slice(0,-1):'0';
    {let r=safe(fullE());setD(r!==null?fmt(r):cur,fullE(),r!==null?'prev':'');}break;
  case'sign':cur=cur.startsWith('-')?cur.slice(1):'-'+cur;setD(cur,fullE());break;
  case'pct':cur=fmt(parseFloat(cur)/100);setD(cur,fullE());break;
  case'dot':if(!cur.includes('.'))cur+='.';setD(cur,fullE());break;
  case'num':if(cur==='0'||cur==='-0')cur=v;else cur+=v;{let r=safe(fullE());setD(r!==null?fmt(r):cur,fullE(),r!==null?'prev':'');}break;
  case'div':buf+=cur+'/';cur='0';setD('0',fullE());break;
  case'mul':buf+=cur+'*';cur='0';setD('0',fullE());break;
  case'sub':buf+=cur+'-';cur='0';setD('0',fullE());break;
  case'add':buf+=cur+'+';cur='0';setD('0',fullE());break;
  case'ob':buf+='(';setD(cur,fullE());break;
  case'cb2':buf+=cur+')';cur='';{let r=safe(fullE());setD(r!==null?fmt(r):fullE(),fullE(),r!==null?'prev':'');}break;
  case'eq':{
    let f=fullE(),r=safe(f);
    if(r===null){setD('Error',f,'err');dNum.classList.add('shake');setTimeout(()=>dNum.classList.remove('shake'),400);return;}
    const step=`${f} = ${fmt(r,true)}`;
    if(showSteps)dSteps.textContent='Step: '+step;
    pushH(f,fmt(r));cur=fmt(r);buf='';setD(fmt(r,true),f+' =');if(typeof checkMilestone==='function')checkMilestone();break;}
  case'sin':{let n=parseFloat(cur),r=Math.sin(n*Math.PI/180);if(showSteps)dSteps.textContent=`sin(${n}°) = ${fmt(r)}`;pushH('sin('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'cos':{let n=parseFloat(cur),r=Math.cos(n*Math.PI/180);if(showSteps)dSteps.textContent=`cos(${n}°) = ${fmt(r)}`;pushH('cos('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'tan':{let n=parseFloat(cur),r=Math.tan(n*Math.PI/180);if(showSteps)dSteps.textContent=`tan(${n}°) = ${fmt(r)}`;pushH('tan('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'log':{let n=parseFloat(cur),r=Math.log10(n);if(showSteps)dSteps.textContent=`log₁₀(${n}) = ${fmt(r)}`;pushH('log('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'ln':{let n=parseFloat(cur),r=Math.log(n);if(showSteps)dSteps.textContent=`ln(${n}) = ${fmt(r)}`;pushH('ln('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'sqrt':{let n=parseFloat(cur),r=Math.sqrt(n);if(showSteps)dSteps.textContent=`√(${n}) = ${fmt(r)}`;pushH('√('+n+')',fmt(r));cur=fmt(r);setD(cur);}break;
  case'sq':{let n=parseFloat(cur),r=n*n;if(showSteps)dSteps.textContent=`${n}² = ${fmt(r)}`;pushH(n+'²',fmt(r));cur=fmt(r);setD(cur);}break;
  case'pow':buf+=cur+'**';cur='0';setD('0',fullE());break;
  case'pi':cur=fmt(Math.PI);if(showSteps)dSteps.textContent='π ≈ 3.14159265358979';setD(cur,'π');break;
  case'eul':cur=fmt(Math.E);if(showSteps)dSteps.textContent='e ≈ 2.71828182845905';setD(cur,'e');break;
  case'fact':{let n=Math.floor(Math.abs(parseFloat(cur)));let r=1;if(n>170)r=Infinity;else for(let i=2;i<=n;i++)r*=i;if(showSteps)dSteps.textContent=`${n}! = ${fmt(r)}`;pushH(n+'!',fmt(r));cur=fmt(r);setD(cur);}break;
  case'abs':{let n=parseFloat(cur),r=Math.abs(n);pushH('|'+n+'|',fmt(r));cur=fmt(r);setD(cur);}break;
  case'inv':{let n=parseFloat(cur),r=1/n;pushH('1/'+n,fmt(r));cur=fmt(r);setD(cur);}break;
  case'ms':mem=parseFloat(cur)||0;updMem();toast('💾 Memory Saved');break;
  case'mr':cur=fmt(mem);setD(cur,fullE());break;
  case'mc':mem=0;updMem();toast('🗑️ Memory Cleared');break;
  case'mplus':mem+=parseFloat(cur)||0;updMem();toast('M+ = '+fmt(mem));break;
  case'mminus':mem-=parseFloat(cur)||0;updMem();toast('M− = '+fmt(mem));break;
}
try{localStorage.setItem('sc_mem',mem);}catch(e){}
